import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BZO4qERu.js";const f=JSON.parse('{"title":"Каналы","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/index.md","filePath":"ru/integrations/channels/index.md","lastUpdated":1792323081000}'),r={name:"ru/integrations/channels/index.md"};function o(n,a,h,s,m,d){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="каналы" tabindex="-1">Каналы <a class="header-anchor" href="#каналы" aria-label="Permalink to &quot;Каналы&quot;">​</a></h1><p>Каналы соединяют Bot в Memoh с чат-платформами. Настраивайте их на вкладке <strong>Platforms</strong> нужного Bot: тогда с одним и тем же Bot можно общаться через Slack, Telegram, Feishu, Discord, WeChat и другие платформы, а также напрямую в приложении Memoh.</p><h2 id="поддерживаемые-каналы" tabindex="-1">Поддерживаемые каналы <a class="header-anchor" href="#поддерживаемые-каналы" aria-label="Permalink to &quot;Поддерживаемые каналы&quot;">​</a></h2><ul><li><a href="./telegram.html">Telegram</a></li><li><a href="./slack.html">Slack</a></li><li><a href="./discord.html">Discord</a></li><li><a href="./feishu.html">Feishu (Lark)</a></li><li><a href="./dingtalk.html">DingTalk</a></li><li><a href="./wecom.html">WeCom</a></li><li><a href="./weixin.html">WeChat</a></li><li><a href="./qq.html">QQ</a></li><li><a href="./line.html">LINE</a></li></ul><p>Что именно поддерживает каждый канал (Markdown, вложения, потоковый вывод, групповые чаты и т. д.), описано в разделе «Ограничения» на его странице.</p><h2 id="общии-порядок-настроики" tabindex="-1">Общий порядок настройки <a class="header-anchor" href="#общии-порядок-настроики" aria-label="Permalink to &quot;Общий порядок настройки&quot;">​</a></h2><ol><li>Зарегистрируйте приложение или Bot на целевой платформе.</li><li>Получите учётные данные: API-токены, идентификаторы приложений, секреты приложений или токены доступа.</li><li>Добавьте канал на вкладке <strong>Platforms</strong> нужного Bot в Memoh.</li><li>Сохраните и включите канал.</li></ol><p>Последний шаг зависит от платформы: где-то нужно вставить URL обратного вызова webhook в консоль платформы, где-то — подтвердить вход по QR-коду с телефона, а где-то Memoh сам поддерживает постоянное stream- или WebSocket-соединение.</p>',8)])])}const _=e(r,[["render",o]]);export{f as __pageData,_ as default};
